bool settings_loaded{};
bool system_dark(){HIGHCONTRASTW high{sizeof(high)};if(SystemParametersInfoW(SPI_GETHIGHCONTRAST,sizeof(high),&high,0)&&high.dwFlags&HCF_HIGHCONTRASTON)return GetSysColor(COLOR_WINDOWTEXT)>GetSysColor(COLOR_WINDOW);HKEY key{};DWORD value=1,size=sizeof(value);if(RegOpenKeyExW(HKEY_CURRENT_USER,L"Software\\Microsoft\\Windows\\CurrentVersion\\Themes\\Personalize",0,KEY_QUERY_VALUE,&key)==ERROR_SUCCESS){RegQueryValueExW(key,L"AppsUseLightTheme",nullptr,nullptr,reinterpret_cast<BYTE*>(&value),&size);RegCloseKey(key);}return value==0;}
std::filesystem::path settings_path(){wchar_t local[32768]{};auto n=GetEnvironmentVariableW(L"LOCALAPPDATA",local,32768);if(!n||n>=32768)return{};return std::filesystem::path(std::wstring(local,n))/L"KRMyceliaNativeMemory"/L"ui-settings.txt";}
int bounded(int value,int high,int fallback){return value>=0&&value<=high?value:fallback;}
AppearanceSettings load_settings(){AppearanceSettings out;auto path=settings_path();std::ifstream file(path,std::ios::binary);std::string line;if(!file||!std::getline(file,line)||(line!="1"&&line!="2"))return out;const bool legacy=line=="1";while(std::getline(file,line)){if(line.rfind("theme=",0)==0){try{out.theme=bounded(std::stoi(line.substr(6)),5,0);if(legacy){constexpr int migrate[]={0,5,0,1,2,3};out.theme=migrate[out.theme];}}catch(...){}}else if(line.rfind("area",0)==0){auto equal=line.find('='),comma=line.find(',',equal);if(equal==std::string::npos||comma==std::string::npos)continue;try{auto area=std::stoi(line.substr(4,equal-4));if(area<0||area>=static_cast<int>(UiArea::count))continue;out.font_sizes[area]=bounded(std::stoi(line.substr(equal+1,comma-equal-1)),3,1);out.colors[area]=bounded(std::stoi(line.substr(comma+1)),6,0);}catch(...){}}}return out;}
AppearanceSettings settings_copy(){std::lock_guard lock(settings_mutex);if(!settings_loaded){cached_settings=load_settings();settings_loaded=true;}return cached_settings;}
COLORREF blend(COLORREF a,COLORREF b,int b_percent){auto mix=[&](int av,int bv){return(av*(100-b_percent)+bv*b_percent)/100;};return RGB(mix(GetRValue(a),GetRValue(b)),mix(GetGValue(a),GetGValue(b)),mix(GetBValue(a),GetBValue(b)));}
double relative_luminance(COLORREF value){auto channel=[](int raw){auto v=raw/255.0;return v<=.04045?v/12.92:std::pow((v+.055)/1.055,2.4);};return .2126*channel(GetRValue(value))+.7152*channel(GetGValue(value))+.0722*channel(GetBValue(value));}
double contrast_ratio(COLORREF a,COLORREF b){auto x=relative_luminance(a),y=relative_luminance(b);if(x<y)std::swap(x,y);return(x+.05)/(y+.05);}
COLORREF readable_text(COLORREF requested,COLORREF background,bool dark){auto adjusted=requested;for(int amount=10;contrast_ratio(adjusted,background)<4.5&&amount<=90;amount+=10)adjusted=blend(requested,dark?RGB(255,255,255):RGB(0,0,0),amount);return adjusted;}
COLORREF selected_color(int index,COLORREF fallback){constexpr COLORREF choices[]={0,RGB(47,111,237),RGB(0,130,114),RGB(110,78,190),RGB(194,111,0),RGB(180,55,93),RGB(80,91,105)};return index>0&&index<7?choices[index]:fallback;}
